add_action( 'woocommerce_after_single_product', 'perfectpixel_short_description_read_more' );

function perfectpixel_short_description_read_more() {
	$cfg = array(
		'height' => max( 40, (int) '{{short_desc_max_height}}' ),
		'more'   => '{{short_desc_more}}',
		'less'   => '{{short_desc_less}}',
	);
	?>
	<script>
	( function ( cfg ) {
		document.querySelectorAll( '.woocommerce-product-details__short-description' ).forEach( function ( box ) {
			if ( box.scrollHeight <= cfg.height + 40 ) {
				return;
			}
			var collapse = function ( on ) {
				box.style.maxHeight = on ? cfg.height + 'px' : 'none';
				box.style.overflow = on ? 'hidden' : '';
				box.style.webkitMaskImage = box.style.maskImage = on ? 'linear-gradient(#000 60%, transparent)' : '';
				link.textContent = on ? cfg.more : cfg.less;
			};
			var link = document.createElement( 'a' );
			link.href = '#';
			link.className = 'perfectpixel-read-more';
			link.style.display = 'inline-block';
			link.style.marginBottom = '1em';
			link.addEventListener( 'click', function ( e ) {
				e.preventDefault();
				collapse( 'none' !== box.style.maxHeight );
			} );
			box.parentNode.insertBefore( link, box.nextSibling );
			collapse( true );
		} );
	} )( <?php echo wp_json_encode( $cfg ); ?> );
	</script>
	<?php
}
